package main
import (
"github.com/gin-gonic/gin"
"net/http"
)
func main() {
r := gin.New()
r.Use(gin.Recovery())
r.Use(func(c *gin.Context) { c.Set("school", "Oak School"); c.Next() })
r.GET("/school", func(c *gin.Context) { c.String(http.StatusOK, c.GetString("school")) })
r.Run("127.0.0.1:3000")
}
